"use client";

/**
 * Laptop mockup: a closed laptop opens its lid, the screen wakes up, then the
 * camera pushes in until the screen fills most of the frame.
 *
 * Written by Better Design. Painted from the theme prop; with no picture the
 * screen shows a placeholder dashboard drawn from the same tokens.
 */
import { AbsoluteFill, Img, interpolate, OffthreadVideo, useCurrentFrame } from "remotion";
import { easings, LAPTOP, LAPTOP_LID, LaptopLid, progress, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

/** Rendered width of the lid, in pixels. The lid and base scale from the real proportions. */
const LID_W = 1000;
const SCALE = LID_W / LAPTOP_LID.width;
const LID_H = LAPTOP_LID.height * SCALE;
const BASE_OVERHANG = LAPTOP.base.overhang * SCALE;
const BASE_H = LAPTOP.base.height * SCALE;
/** Shell and dark-screen inks. They stay the same in both modes, like real hardware. */
const SHELL = "oklch(0.3 0.006 260)";
const OFF = "oklch(0.12 0.004 260)";
const VIDEO = /\.(mp4|webm|mov)(\?.*)?$/i;

/** Timing, in frames. */
const OPEN_AT = 8;
const OPEN_FRAMES = 44;
const LIGHT_AT = 46;
const PUSH_AT = 68;
const PUSH_FRAMES = 44;

export interface LaptopMockupProps {
  /** Image or video for the screen. A path ending in .mp4, .webm or .mov plays as video. */
  src?: string;
  theme?: Partial<VideoTheme>;
}

function PlaceholderDashboard({ theme }: { theme: VideoTheme }) {
  const bar = (w: string, h: number, c = withAlpha(theme.foreground, 0.12)) => <div style={{ width: w, height: h, borderRadius: h / 2, background: c }} />;
  const heights = [0.42, 0.58, 0.5, 0.72, 0.64, 0.86, 0.78];
  return (
    <div style={{ position: "absolute", inset: 0, background: theme.background, display: "flex" }}>
      <div style={{ width: 190, padding: "26px 20px", borderRight: `1px solid ${theme.border}`, background: theme.card, display: "flex", flexDirection: "column", gap: 18 }}>
        <div style={{ width: 34, height: 34, borderRadius: 10, background: theme.primary, marginBottom: 12 }} />
        {[0.8, 0.62, 0.7, 0.54, 0.66].map((w, i) => (
          <div key={i} style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 10px", borderRadius: 8, background: i === 0 ? theme.accent : "transparent" }}>
            <div style={{ width: 14, height: 14, borderRadius: 4, background: i === 0 ? theme.primary : withAlpha(theme.foreground, 0.2) }} />
            {bar(`${w * 100}%`, 9, withAlpha(theme.foreground, i === 0 ? 0.6 : 0.2))}
          </div>
        ))}
      </div>
      <div style={{ flex: 1, padding: 28, display: "flex", flexDirection: "column", gap: 20 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          {bar("32%", 18, withAlpha(theme.foreground, 0.8))}
          <div style={{ width: 110, height: 34, borderRadius: 17, background: theme.primary }} />
        </div>
        <div style={{ display: "flex", gap: 16 }}>
          {[0.5, 0.64, 0.42].map((w, i) => (
            <div key={i} style={{ flex: 1, padding: 18, borderRadius: 14, background: theme.card, border: `1px solid ${theme.border}`, display: "flex", flexDirection: "column", gap: 12 }}>
              {bar("46%", 9)}
              {bar(`${w * 100}%`, 20, withAlpha(theme.foreground, 0.75))}
            </div>
          ))}
        </div>
        <div style={{ flex: 1, padding: 22, borderRadius: 14, background: theme.card, border: `1px solid ${theme.border}`, display: "flex", alignItems: "flex-end", gap: 18 }}>
          {heights.map((h, i) => (
            <div key={i} style={{ flex: 1, height: `${h * 100}%`, borderRadius: 8, background: i === heights.length - 2 ? theme.primary : withAlpha(theme.primary, 0.22) }} />
          ))}
        </div>
      </div>
    </div>
  );
}

/** A laptop that opens, lights its screen and pushes in to it. */
export function LaptopMockup({ src, theme: themeOverride }: LaptopMockupProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();

  const open = easings.inOut(progress(frame, OPEN_AT, OPEN_FRAMES));
  const lidAngle = interpolate(open, [0, 1], [-90, 4]);
  const light = easings.out(progress(frame, LIGHT_AT, 22));
  const push = easings.inOut(progress(frame, PUSH_AT, PUSH_FRAMES));
  const scale = interpolate(push, [0, 1], [0.78, 1.52]);
  const shiftY = interpolate(push, [0, 1], [60, 40]);
  const enter = easings.out(progress(frame, 0, 14));
  const hide = 1 - easings.out(progress(frame, PUSH_AT + 10, 26));

  const screen = src ? (
    VIDEO.test(src) ? (
      <OffthreadVideo src={src} muted style={{ width: "100%", height: "100%", objectFit: "cover" }} />
    ) : (
      <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
    )
  ) : (
    <PlaceholderDashboard theme={theme} />
  );

  return (
    <AbsoluteFill
      style={{
        background: `radial-gradient(ellipse 70% 60% at 50% 46%, ${withAlpha(theme.primary, 0.12 * light)}, ${theme.background} 72%), ${theme.background}`,
        alignItems: "center",
        justifyContent: "center",
        perspective: 2600,
        perspectiveOrigin: "50% 20%",
      }}
    >
      <div
        style={{
          position: "relative",
          width: LID_W,
          height: LID_H,
          transformStyle: "preserve-3d",
          opacity: enter,
          transform: `translateY(${shiftY}px) scale(${scale})`,
        }}
      >
        {/* Lid: the screen face and the shell face share one hinge. */}
        <div style={{ position: "absolute", inset: 0, transformOrigin: "50% 100%", transform: `rotateX(${lidAngle}deg)`, transformStyle: "preserve-3d" }}>
          <div style={{ position: "absolute", left: 0, top: 0, transform: `scale(${SCALE})`, transformOrigin: "0 0", backfaceVisibility: "hidden" }}>
            <LaptopLid
              overlay={<div style={{ position: "absolute", inset: 0, background: "linear-gradient(160deg, oklch(1 0 0 / 0.1), oklch(1 0 0 / 0) 40%)" }} />}
            >
              <div style={{ position: "absolute", inset: 0, background: OFF }} />
              <div style={{ position: "absolute", inset: 0, opacity: light, filter: `brightness(${0.6 + light * 0.4})` }}>{screen}</div>
            </LaptopLid>
          </div>
          <div
            style={{
              position: "absolute",
              inset: 0,
              borderRadius: `${LAPTOP.lidCorner * SCALE}px ${LAPTOP.lidCorner * SCALE}px 6px 6px`,
              background: `linear-gradient(180deg, oklch(0.42 0.006 260), ${SHELL})`,
              transform: "rotateY(180deg)",
              backfaceVisibility: "hidden",
            }}
          />
        </div>
        {/* Base: a slab with a lip and a thumb notch, plus its contact shadow. */}
        <div style={{ position: "absolute", left: -BASE_OVERHANG, right: -BASE_OVERHANG, top: LID_H - 2, height: BASE_H, opacity: hide * 0.3 + 0.7 }}>
          <div style={{ position: "absolute", inset: 0, borderRadius: "4px 4px 22px 22px", background: `linear-gradient(180deg, oklch(0.5 0.006 260), ${SHELL} 60%, oklch(0.24 0.006 260))` }} />
          <div style={{ position: "absolute", left: "50%", top: 0, width: 150, height: 10, marginLeft: -75, borderRadius: "0 0 10px 10px", background: "oklch(0.26 0.006 260)" }} />
          <div
            style={{
              position: "absolute",
              left: 40,
              right: 40,
              top: 34,
              height: 40,
              borderRadius: "50%",
              background: "oklch(0 0 0 / 0.2)",
              filter: "blur(18px)",
            }}
          />
        </div>
      </div>
    </AbsoluteFill>
  );
}
